import{_ as i,o as a,c as e,a7 as t}from"./chunks/framework.DUCm5Bu5.js";const c=JSON.parse('{"title":"빠른 시작","description":"빌드한 저장소에서 격리된 로컬 서버를 시작하고 실행 여부를 확인합니다.","frontmatter":{"title":"빠른 시작","description":"빌드한 저장소에서 격리된 로컬 서버를 시작하고 실행 여부를 확인합니다.","updated":"2026-10-18T00:00:00.000Z"},"headers":[],"relativePath":"ko/getting-started/quickstart.md","filePath":"ko/getting-started/quickstart.md"}'),l={name:"ko/getting-started/quickstart.md"};function h(n,s,d,o,p,r){return a(),e("div",null,[...s[0]||(s[0]=[t('<p>이 페이지는 <a href="./installation">설치</a>에서 빌드한 저장소를 사용해 메모리 지속성을 가진 로컬 격리 서버를 시작합니다. 게임 리스너가 없는 <code>management</code> 프로필로 첫 성공 확인을 수행한 뒤, <code>kr-812</code> 같은 게임 프로필이 어떻게 다른지, 그리고 이 검사가 무엇을 증명하고 무엇을 증명하지 않는지 설명합니다.</p><p><strong>이 페이지의 대상:</strong> 소스 빌드를 마쳤고 몇 분 안에 로컬 서버를 실행하려는 사용자입니다.</p><h2 id="얻게-되는-것" tabindex="-1">얻게 되는 것 <a class="header-anchor" href="#얻게-되는-것" aria-label="Permalink to &quot;얻게 되는 것&quot;">​</a></h2><p>안전하게 시작하고 중지할 수 있는 로컬 서버 프로세스이며, 메모리 지속성을 사용하고 실제 데이터베이스에는 연결하지 않습니다. 프로세스가 종료되면 계정과 진행 상황이 초기화됩니다. 완전히 플레이할 수 있는 서버가 아니며, 게임 클라이언트가 동작한다는 증거도 아닙니다.</p><p><code>management</code> 프로필은 관리 API와 WebUI만 시작하고 게임 또는 릴레이 리스너가 없으므로 클라이언트 데이터 없이도 실행됩니다. <code>kr-812</code> 같은 게임 프로필은 해당 빌드의 로컬 클라이언트 데이터가 추가로 필요하며, 저장소에는 그 데이터가 포함되어 있지 않습니다.</p><h2 id="시작하기-전에" tabindex="-1">시작하기 전에 <a class="header-anchor" href="#시작하기-전에" aria-label="Permalink to &quot;시작하기 전에&quot;">​</a></h2><ul><li><a href="./installation">설치</a>를 마쳤습니다. 솔루션이 경고 없이 빌드되었고 빌드 출력이 존재합니다.</li><li>터미널이 저장소 루트에 있습니다. 이 페이지의 모든 명령은 여기서 실행합니다.</li><li>.NET 10 SDK를 사용할 수 있습니다. <code>dotnet --version</code>이 10.x를 출력합니다.</li><li>로컬 검사 패치가 있습니다. PowerShell에서는 <code>Test-Path tools/local-checks/isolated-memory.patch.yaml</code>, POSIX 셸에서는 <code>test -f tools/local-checks/isolated-memory.patch.yaml</code>로 확인하세요.</li><li>다음 단계에서 <code>.env</code> 파일을 만듭니다.</li><li>선택 사항: 이번에 <code>kr-812</code>를 시작하려면 일치하는 클라이언트 데이터가 <code>client-data/kr-812/data</code> 또는 <code>client-data/kr-812/dataraw</code> 아래에 있어야 합니다.</li></ul><h2 id="로컬-환경-변수-파일-준비" tabindex="-1">로컬 환경 변수 파일 준비 <a class="header-anchor" href="#로컬-환경-변수-파일-준비" aria-label="Permalink to &quot;로컬 환경 변수 파일 준비&quot;">​</a></h2><p>프로필은 구성되는 시점에 환경 변수를 치환하며, 이때는 아직 어떤 패치도 서비스를 비활성화하지 않았습니다. 따라서 메모리 검사에서도 로컬 MySQL 비밀번호 변수가 있어야 합니다.</p><h3 id="_1-예제-파일-복사" tabindex="-1">1. 예제 파일 복사 <a class="header-anchor" href="#_1-예제-파일-복사" aria-label="Permalink to &quot;1. 예제 파일 복사&quot;">​</a></h3><p>PowerShell:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Copy-Item</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> .env.example .env</span></span></code></pre></div><p>Linux 셸:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span></code></pre></div><p><code>.env</code>는 Git에서 제외되므로 절대 커밋하지 마세요.</p><h3 id="_2-임시-비밀번호-설정" tabindex="-1">2. 임시 비밀번호 설정 <a class="header-anchor" href="#_2-임시-비밀번호-설정" aria-label="Permalink to &quot;2. 임시 비밀번호 설정&quot;">​</a></h3><p><code>.env</code>를 열고 <code>BFF_MYSQL_PASSWORD</code>를 비어 있지 않은 임시 값(예: <code>isolated-check-only</code>)으로 설정하세요. <code>persistence.mysql</code> 행은 기본값이 없는 <code>${BFF_MYSQL_PASSWORD}</code>를 읽으므로 변수가 없으면 구성이 실패합니다. 격리 메모리 패치는 구성 이후에만 해당 행을 비활성화합니다. 로컬 검사에는 실제 데이터베이스 자격 증명을 사용하지 말고, 실제 자격 증명은 의도적으로 구성한 배포에서만 사용하세요.</p><p><strong>확인:</strong> <code>.env</code>가 존재하고(<code>Test-Path .env</code>가 <code>True</code> 출력) <code>BFF_MYSQL_PASSWORD</code> 줄이 비어 있지 않습니다. 이 파일이나 값을 채팅이나 이슈에 붙여 넣지 마세요.</p><h2 id="프로필-찾기" tabindex="-1">프로필 찾기 <a class="header-anchor" href="#프로필-찾기" aria-label="Permalink to &quot;프로필 찾기&quot;">​</a></h2><p>프로필은 클라이언트 빌드를 지정하고 그 빌드가 사용하는 플러그인 행을 구성합니다. id는 <code>&lt;region&gt;-&lt;wire version&gt;</code> 형식이며, 숫자는 실행 파일의 파일 버전이 아니라 클라이언트의 <code>ClientVersion_Major</code>입니다. <code>management</code>는 관리 전용 프로필이고 <code>setup</code>은 첫 실행 도우미입니다.</p><h3 id="_1-패키지-프로필-나열" tabindex="-1">1. 패키지 프로필 나열 <a class="header-anchor" href="#_1-패키지-프로필-나열" aria-label="Permalink to &quot;1. 패키지 프로필 나열&quot;">​</a></h3><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dotnet run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">project src</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BubbleFighter.Fantasy.Host </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c Release </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> profiles list</span></span></code></pre></div><p>각 프로필마다 id와 설명 한 줄이 출력됩니다. 이 버전에는 19개가 있습니다. 그중 유용한 두 줄은 <code>management</code>(&quot;Administration and durable storage only; no game or relay ports.&quot;)와 <code>kr-812</code>(&quot;Korean 2015 client build, ClientVersion_Major 812, resource patch 458.&quot;)입니다.</p><p>프로필이 목록에 있다고 해서 해당 빌드의 모든 게임 기능이 구현되었다는 뜻은 아닙니다. 프로필마다 사용 가능한 기능과 필요한 데이터가 다릅니다.</p><h3 id="_2-검색된-플러그인-나열" tabindex="-1">2. 검색된 플러그인 나열 <a class="header-anchor" href="#_2-검색된-플러그인-나열" aria-label="Permalink to &quot;2. 검색된 플러그인 나열&quot;">​</a></h3><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dotnet run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">project src</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BubbleFighter.Fantasy.Host </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c Release </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> plugins list</span></span></code></pre></div><p>각 플러그인 정의마다 플러그인 id, 버전, 지원 클라이언트 빌드, 로드된 위치가 한 줄씩 출력됩니다. 이것이 Host가 프로필에 마운트할 수 있는 구현 집합입니다.</p><p><strong>확인:</strong> 두 명령이 모두 성공적으로 종료되고 내용을 출력하며, 프로필이나 플러그인 스캔 오류가 없습니다.</p><h2 id="적용되는-구성-확인" tabindex="-1">적용되는 구성 확인 <a class="header-anchor" href="#적용되는-구성-확인" aria-label="Permalink to &quot;적용되는 구성 확인&quot;">​</a></h2><p>로컬 검사 패치로 <code>kr-812</code>를 구성하고 아무것도 시작하지 않은 채 결과를 출력합니다.</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dotnet run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">project src</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BubbleFighter.Fantasy.Host </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c Release </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">profile kr</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">812</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">patch tools</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">local</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">checks</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">isolated</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">memory.patch.yaml </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dump</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">config</span></span></code></pre></div><p>명령은 적용되는 행 목록을 YAML로 출력하고 종료 코드 0으로 끝납니다. 출력에서 다음을 찾으세요.</p><ul><li><code>id: persistence.mysql</code> 뒤에 <code>disabled: true</code>가 있음</li><li><code>id: persistence.memory</code>에 <code>disabled: true</code>가 없으므로 활성화됨</li><li><code>id: clientdata</code>에 <code>kr-812</code>의 해석된 <code>data_directory</code>와 <code>raw_directory</code>가 표시됨</li></ul><p>격리 패치는 마지막에 적용되므로 MySQL을 실제 데이터베이스로 지정한 개발자 <code>.env</code>나 <code>local.patch.yaml</code>을 덮어씁니다. 덤프는 어떤 플러그인도 활성화되기 전에 끝나므로 구성과 유효성 검사만 증명하며 프로필이 시작된다는 것은 증명하지 않습니다.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>패치가 MySQL을 활성화하면 덤프에 자격 증명을 포함한 치환된 값이 들어갈 수 있습니다. 민감한 정보로 취급하세요.</p></div><h2 id="서버-시작" tabindex="-1">서버 시작 <a class="header-anchor" href="#서버-시작" aria-label="Permalink to &quot;서버 시작&quot;">​</a></h2><h3 id="_1-게임-없는-로컬-서버-시작" tabindex="-1">1. 게임 없는 로컬 서버 시작 <a class="header-anchor" href="#_1-게임-없는-로컬-서버-시작" aria-label="Permalink to &quot;1. 게임 없는 로컬 서버 시작&quot;">​</a></h3><p>저장소 루트에서 실행하세요.</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dotnet run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">project src</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BubbleFighter.Fantasy.Host </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c Release </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">profile management </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">patch tools</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">local</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">checks</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">isolated</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">memory.patch.yaml</span></span></code></pre></div><p>저장소 루트에 <code>.env</code>가 있으면 첫 줄이 <code>Loaded unset variables from &lt;path&gt;.</code>입니다. 이어서 서버가 관리 리스너, WebUI 주소, 활성 행 수를 출력합니다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Row &#39;admin.http&#39; admin API listening on 127.0.0.1:8080.</span></span>\n<span class="line"><span>WebUI: http://127.0.0.1:8080/</span></span>\n<span class="line"><span>Server started with &lt;count&gt; active row(s).</span></span></code></pre></div><p><code>&lt;count&gt;</code>는 Host가 출력하는 활성 행 수이며 고정된 숫자가 아닙니다. <code>management</code>에는 게임 또는 릴레이 포트가 없습니다. 관리 API 기본 주소는 <code>http://127.0.0.1:8080</code>이며, <code>profiles/bundles/core.yaml</code>의 <code>admin.http</code> 행(<code>${BFF_ADMIN_HOST:-127.0.0.1}:${BFF_ADMIN_PORT:-8080}</code>)에서 옵니다. 프로세스는 중지할 때까지 포그라운드에서 유지됩니다.</p><h3 id="_2-게임-프로필-시작-클라이언트-데이터-필요" tabindex="-1">2. 게임 프로필 시작(클라이언트 데이터 필요) <a class="header-anchor" href="#_2-게임-프로필-시작-클라이언트-데이터-필요" aria-label="Permalink to &quot;2. 게임 프로필 시작(클라이언트 데이터 필요)&quot;">​</a></h3><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dotnet run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">project src</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BubbleFighter.Fantasy.Host </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c Release </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">profile kr</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">812</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">patch tools</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">local</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">checks</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">isolated</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">memory.patch.yaml</span></span></code></pre></div><p>게임 프로필에는 일치하는 클라이언트 데이터가 필요합니다. 없으면 <code>clientdata</code> 행이 실패하고 시작이 다음 메시지와 함께 중단됩니다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>clientdata: neither data_directory &#39;&lt;working-directory&gt;/client-data/kr-812/data&#39; nor raw_directory &#39;&lt;working-directory&gt;/client-data/kr-812/dataraw&#39; exists. Provision the configured client-data directories before enabling this row.</span></span></code></pre></div><p>데이터를 제공하거나 <a href="./installation">설치</a>에서 설명한 설치 도우미로 가져온 뒤 프로필을 다시 시작하세요. 데이터가 준비되면 <code>kr-812</code>는 <code>${BFF_BIND_HOST:-0.0.0.0}:${LEGACY_PORT}</code>에 게임 리스너를 바인딩합니다. <code>profiles/kr-812/profile.yaml</code>이 <code>LEGACY_PORT</code>를 <code>${KR_812_GAME_PORT:-7110}</code>로 설정하므로 실제 값은 <code>0.0.0.0:7110</code>입니다. 레거시 빌드에는 릴레이 리스너가 없습니다. 관리 API는 계속 <code>127.0.0.1:8080</code>입니다.</p><p><strong>확인:</strong> 프로세스가 포그라운드에 유지되고 위의 시작 줄 세 개를 출력하며 활성화 오류로 종료되지 않습니다.</p><h2 id="실행-여부-확인" tabindex="-1">실행 여부 확인 <a class="header-anchor" href="#실행-여부-확인" aria-label="Permalink to &quot;실행 여부 확인&quot;">​</a></h2><h3 id="_1-상태-확인-엔드포인트" tabindex="-1">1. 상태 확인 엔드포인트 <a class="header-anchor" href="#_1-상태-확인-엔드포인트" aria-label="Permalink to &quot;1. 상태 확인 엔드포인트&quot;">​</a></h3><p>PowerShell:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-RestMethod</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> http:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">127.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8080</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">health</span></span></code></pre></div><p>Linux 셸:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8080/health</span></span></code></pre></div><p>응답에는 <code>status</code> = <code>ok</code>와 UTC 타임스탬프가 들어 있습니다. admin 토큰을 설정해도 <code>/health</code>는 항상 열려 있습니다.</p><h3 id="_2-런타임-인스턴스-확인" tabindex="-1">2. 런타임 인스턴스 확인 <a class="header-anchor" href="#_2-런타임-인스턴스-확인" aria-label="Permalink to &quot;2. 런타임 인스턴스 확인&quot;">​</a></h3><p>PowerShell:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-RestMethod</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> http:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">127.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8080</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">api</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">plugins </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Format-Table</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> rowId</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> state</span></span></code></pre></div><p>Linux 셸:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8080/api/plugins</span></span></code></pre></div><p><code>/api/plugins</code>는 실행 중인 플러그인 행을 반환합니다. 각 항목에는 <code>rowId</code>, <code>plugin</code>, <code>source</code>, <code>state</code>, <code>error</code>가 있습니다. <code>state</code> = <code>Active</code>이고 <code>error</code>가 비어 있는 행을 찾으세요. <code>Failed</code> 또는 <code>Pending</code> 행은 <code>error</code>에 진단 정보를 담고 있습니다.</p><p><code>.env</code>에서 <code>BFF_ADMIN_TOKEN</code>을 설정했다면 모든 <code>/api</code> 호출에 bearer 토큰이 필요합니다. <code>Invoke-RestMethod</code>에는 <code>-Headers @{ Authorization = &quot;Bearer &lt;token&gt;&quot; }</code>를, <code>curl</code>에는 <code>-H &quot;Authorization: Bearer &lt;token&gt;&quot;</code>를 추가하세요. WebUI 파일과 <code>/health</code>는 브라우저가 로그인 페이지를 불러올 수 있도록 항상 열려 있습니다.</p><h3 id="_3-webui-열기" tabindex="-1">3. WebUI 열기 <a class="header-anchor" href="#_3-webui-열기" aria-label="Permalink to &quot;3. WebUI 열기&quot;">​</a></h3><p>브라우저에서 <code>http://127.0.0.1:8080/</code>을 여세요. management 프로필은 관리 인터페이스를 제공합니다.</p><p><strong>확인:</strong> 상태 확인이 <code>ok</code>를 반환하고, 인스턴스 목록에 활성 행이 보이며, WebUI가 열립니다. 이 검사는 Host와 관리 API가 실행 중임을 증명하며, 게임 클라이언트가 연결할 수 있음을 증명하지는 않습니다.</p><h2 id="서버-중지" tabindex="-1">서버 중지 <a class="header-anchor" href="#서버-중지" aria-label="Permalink to &quot;서버 중지&quot;">​</a></h2><p>서버를 실행 중인 터미널에서 Ctrl+C를 누릅니다. 콘솔에 <code>Shutdown complete.</code>가 출력되고 프로세스가 종료됩니다. 메모리의 계정과 진행 상황은 프로세스와 함께 사라집니다. 로컬 검사에서는 지속 데이터를 건드리지 않으므로 중지는 항상 안전합니다.</p><p>재시작 후에도 데이터를 유지하려면 <a href="./../guides/configuration">서버 설정</a>에 따라 지속성을 SQLite 또는 MySQL로 전환하세요. 격리 메모리 패치는 로컬 검사 전용입니다.</p><h2 id="이것이-증명하지-않는-것" tabindex="-1">이것이 증명하지 않는 것 <a class="header-anchor" href="#이것이-증명하지-않는-것" aria-label="Permalink to &quot;이것이 증명하지 않는 것&quot;">​</a></h2><ul><li>게임 클라이언트 로그인도, 게임 플레이나 패킷 호환성 검증도 없습니다.</li><li>management 프로필에는 게임 또는 릴레이 리스너가 없으므로 클라이언트 트래픽이 전혀 없습니다.</li><li>구성 검사나 자동 검사 통과는 실제 클라이언트 수용 테스트가 아닙니다. 실제 클라이언트로 로그인과 대상 게임 흐름을 별도로 테스트하세요.</li></ul><h2 id="문제가-발생하면" tabindex="-1">문제가 발생하면 <a class="header-anchor" href="#문제가-발생하면" aria-label="Permalink to &quot;문제가 발생하면&quot;">​</a></h2><ul><li><strong><code>environment variable &#39;BFF_MYSQL_PASSWORD&#39; is not set and has no default</code>:</strong> <code>.env</code> 파일이 없거나 저장소 루트에서 찾지 못했거나 변수를 설정하지 않았습니다. <code>.env.example</code>을 복사하고 임시 값을 설정하세요.</li><li><strong>관리 포트가 이미 사용 중:</strong> 리스너 행에서 시작이 실패합니다. <code>.env</code>에서 <code>BFF_ADMIN_PORT</code>를 설정하거나 8080을 점유한 프로세스를 중지하세요.</li><li><strong>게임 포트가 이미 사용 중:</strong> <code>.env</code>에서 <code>KR_812_GAME_PORT</code>를 설정하거나 7110을 점유한 프로세스를 중지하세요.</li><li><strong><code>kr-812</code>가 <code>clientdata</code> 때문에 실패:</strong> 위의 클라이언트 데이터 메시지를 참고하세요. 해당 빌드의 데이터가 있어야 프로필이 시작됩니다.</li><li><strong><code>Server startup did not converge</code>:</strong> 메시지가 비활성 행마다 상태와 진단을 나열합니다. 첫 번째 <code>Failed</code> 또는 <code>Pending</code> 행을 읽고 원인을 고치세요.</li></ul><p>더 많은 사례는 <a href="./../guides/troubleshooting">문제 해결</a>에서 다룹니다.</p><h2 id="다음-단계" tabindex="-1">다음 단계 <a class="header-anchor" href="#다음-단계" aria-label="Permalink to &quot;다음 단계&quot;">​</a></h2><p><a href="./../guides/configuration">서버 설정</a>에서 지속성, 포트, 프로필, 환경 변수를 살펴보고, <a href="./../guides/plugins">플러그인</a>에서 플러그인 행의 동작 방식과 직접 만든 플러그인을 마운트하는 방법을 확인하세요. 클라이언트를 설치하고 서버에 연결하는 동반 런처는 <a href="./../guides/launcher">런처</a>를 참고하십시오.</p>',75)])])}const g=i(l,[["render",h]]);export{c as __pageData,g as default};
